package net.civeira.phylax.features.access.userwebauthncredential.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class AuthenticatorVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property authenticator of user webauthn credential ")
  void test_authenticator_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> AuthenticatorVO.tryFrom(null));
    Assertions.assertEquals("one", AuthenticatorVO.from("one").getAuthenticator());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> AuthenticatorVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", AuthenticatorVO.from("one").toString());
  }
}
